  str_n32_multiline_9_name_desc = "—",
  str_n32_multiline_10_name_desc = "โศกนาฏกรรมยังคงหาทางโจมตี แต่คุณไม่มีเวลาหยุดพัก",
  str_n32_multiline_11_name_desc = "แผนสำหรับการเดินทางย้อนเวลาครั้งสุดท้ายได้ถูกจัดทำขึ้น ตอนนี้การแข่งขันกับเวลาเริ่มต้นขึ้น",
  str_n32_multiline_12_name_desc = "คุณพบ Dark Angel แต่การเอาใจเธออาจยากกว่าที่คิด...",
  str_n32_multiline_13_name_desc = "การกระพือปีกของผีเสื้ออาจทำให้เกิดพายุเฮอริเคนได้ ในไม่ช้าชิ้นส่วนทั้งหมดของคุณจะเรียงตัวกัน",
  str_n32_multiline_14_name_desc = "—",
  str_n32_multiline_15_name_desc = "มีเพียงราชินีขาวเท่านั้นที่ยังคงอยู่บนกระดาน และเธอเดิมพันทั้งหมดด้วยการเคลื่อนไหวครั้งสุดท้ายที่สิ้นหวัง",
  str_n32_multiline_16_name_desc = "—",
  str_n32_multiline_17_name_desc = "เมื่อได้รับเชิญให้เข้าไปในห้องโถงใหญ่ของคฤหาสน์ชวาร์ตษ์ คุณจะได้ยินใครบางคนกำลังพูดอยู่อีกด้านของประตู",
  str_n32_multiline_18_name_desc = "ขณะที่คุณเตรียมจะออกจาก Schwartz Mansion คุณพบกองจดหมายที่ถูกเผาอยู่กลางสนามหญ้าในสวนหลังบ้าน...",
  str_n32_multiline_19_name_desc = "บนถนนสายเล็กๆ ที่มุ่งสู่คฤหาสน์ชวาร์ตษ์ เด็กสาวผมแดงจู่ๆ ก็ขวางเส้นทางของชาโรน่า",
  str_n32_multiline_20_name_desc = "ซ่อนตัวอยู่ใกล้จัตุรัสกลาง คุณได้ยินการสนทนาระหว่างเพื่อนเก่าสองคนโดยไม่ได้ตั้งใจ",
  str_n32_multiline_21_name_desc = "บนถนนในอัพทาวน์ คนที่ดูเหมือนไม่เกี่ยวข้องกันสองคนกำลังคุยกันเกี่ยวกับบางสิ่งที่ทำให้คุณสนใจ...",
  str_n32_multiline_22_name_desc = "บนถนนสายเล็ก ๆ ที่มุ่งสู่ Schwartz Mansion หอคอยสูงพังทลายลงด้วยการชน...",
  str_n32_multiline_23_name_desc = "ท่ามกลางความโกลาหล คุณพบว่ามีขุนนางสองคนติดอยู่ตรงจุดนั้น",
  str_n32_multiline_24_name_desc = "บนถนนสายเล็กๆ ที่มุ่งหน้าสู่ Schwartz Mansion หอคอยสูงถล่มลงมา...",
  str_n32_multiline_1_name_desc_long = "จาคีนล้มเหลว คุณไม่สามารถออกจาก Crystal of Eternal Memory ได้ แต่สามารถย้อนเวลากลับไปก่อนที่ขบวนพาเหรดจะเริ่มต้นได้สำเร็จ Joshua ซึ่งกลายเป็นสัตว์ประหลาดที่รู้จักกันในชื่อ Dark Angel โจมตีคุณอีกครั้ง หลังจากต่อสู้กับเธอ คุณพยายามที่จะจากไป ทั้ง ๆ ที่คุณสิ้นหวังมากขึ้นเรื่อยๆ แต่ก็ยังไม่มีความคืบหน้า ในขณะนี้ โยชูวาอีกคนหนึ่งปรากฏขึ้น",
  str_n32_multiline_2_name_desc_long = "โจชัวอธิบายเรื่องราวทั้งหมดให้คุณฟัง ปรากฎว่า Joshua ไม่เคยตาย แต่ได้กักขังตัวเองและบุคลิกที่ควบคุมไม่ได้ซึ่งแตกออกจากเมล็ดพันธุ์ของเธอไปยัง Crystal of Eternal Memory เพื่อช่วย Joshua และออกจากสถานที่นี้ คุณต้องวางแผนปราบปราม Dark Angel",
  str_n32_multiline_3_name_desc_long = "คุณแบ่งออกเป็นสองกลุ่มตามแผน มีอามาถึงอัฒจันทร์ ขณะที่คนอื่นๆ ล่อดาร์คแองเจิ้ลออกมาได้สำเร็จ สิ่งต่าง ๆ ดูเหมือนจะดำเนินไปอย่างสมบูรณ์แบบเมื่อการก่อจลาจลเริ่มต้นขึ้นก่อนกำหนดโดยไม่ทราบสาเหตุ ศัตรูแปลก ๆ และมังกรที่ดูแปลกหน้าโจมตีอัฒจันทร์ ทำให้แผนของคุณเข้าสู่ความโกลาหล",
  str_n32_multiline_4_name_desc_long = "คุณเอาชนะ Dark Angel ได้ แต่สถานการณ์รอบตัวคุณจมดิ่งสู่ความสิ้นหวังในวินาทีต่อมา กองกำลังกบฎ มังกรบิน และความคลั่งไคล้ที่เพิ่มขึ้นแพร่กระจายไปทั่วฝูงชนอย่างต่อเนื่อง แม้กระทั่งเปลี่ยนใบหน้าของโจชัวให้กลายเป็นภาพแห่งความดุร้ายที่ยากจะจดจำ สหายของคุณถูกอบายมุขกลืนกินไปทีละคน และเมื่อคุณจมดิ่งสู่ความสิ้นหวัง Jakine ร่ายมนตร์การเดินทางข้ามเวลาอีกครั้ง...",
  str_n32_multiline_5_name_desc_long = "เวลาไหลย้อนกลับ และทุกคนในสวนมีส่วนร่วมในการต่อสู้กับ Dark Angel อีกครั้ง มีเพียงคุณเท่านั้นที่ยังคงถูกไล่ตามโดยผู้คุมด้วยสีหน้าอันน่าขนลุก... นี่มันเกิดอะไรขึ้นกันแน่? ขณะที่คุณซ่อนตัว ยึดมั่นในชีวิตที่รัก คุณก็หลงอยู่ในฌาน",
  str_n32_multiline_6_name_desc_long = "เช่นเดียวกับครั้งแรกที่คุณย้อนเวลากลับไป ทุกคนได้พบกับ Joshua อีกครั้ง แต่ครั้งนี้ดูเหมือนว่า Schwartz และ Joshua จะหมางเมินกัน ด้วยเหตุนี้ คาเลบจึงถูกทิ้งไว้ข้างกายของจาคีน ส่วนชวาร์ตษ์เผชิญหน้ากับดาร์คแองเจิ้ลเพียงลำพัง",
  str_n32_multiline_7_name_desc_long = "ในการต่อสู้แบบตัวต่อตัว Schwartz และ Dark Angel นั้นก้ำกึ่ง แต่จู่ๆ Dark Angel ก็พูดด้วยเสียงของ Joshua ประณามพฤติกรรมที่ขาดความรับผิดชอบของ Schwartz ที่มีต่อครอบครัวของเขา ในขณะเดียวกัน การก่อจลาจลก็เริ่มต้นขึ้น และคุณตระหนักว่าคุณต้องฉวยโอกาสนี้เพื่อรวมกลุ่มกับคนอื่นๆ อย่างไรก็ตาม ในขณะนี้ คุณได้เห็น Dark Angel หยุดมังกรไม่ให้โจมตีอัฒจันทร์",
  str_n32_multiline_8_name_desc_long = "คราวนี้มีอารอด อย่างไรก็ตาม สาวน้อย Carleen ได้รับผลกระทบจากอาการบาดเจ็บ และเลือกที่จะปลิดชีวิตตัวเองเพื่อปกป้องครอบครัวของเธอ วิญญาณของ Mia กำลังจะแตกสลายภายใต้สถานการณ์ ในขณะนั้น Dark Angel ที่กำลังจะตายได้อุ้ม Mia ไว้ในอ้อมแขนของเธอและกอดเธอไว้แน่น ในขณะนี้เองที่ Schwartz เชื่อมั่นว่า Dark Angel เป็นภรรยาของเขาจริงๆ",
  str_n32_multiline_9_name_desc_long = "ในคฤหาสน์ โจชัวอธิบายความจริงให้คาเลบฟัง ปรากฎว่า Joshua เป็นผู้ลอบสังหารฝ่ายตรงข้ามของ Schwartz ไม่ใช่น้องสาวแท้ๆ ของ Caleb เธอพยายามเกลี้ยกล่อมให้ Caleb ช่วยกำจัดคนอื่นๆ และแม้ว่า Caleb จะไม่สงสัยในตัวตนของ Joshua แต่เขาก็ไม่เต็มใจที่จะช่วยเหลือเธอ และท้ายที่สุดก็ถูก Joshua ฆ่าตาย",
  str_n32_multiline_10_name_desc_long = "คุณและ Mia มาถึงคฤหาสน์เพื่อค้นหาที่พักด้วยความโกลาหล และด้วยความช่วยเหลือจากคุณ Rot คุณก็สามารถหลบหนีพร้อมกับ Jakine ได้ คุณชี้แจงความจริงของเรื่องนี้อย่างคร่าว ๆ โดยการจัดข้อมูลข่าวกรองที่ได้รับจากการเดินทางสองครั้ง การเดินทางย้อนเวลาครั้งนี้จะเป็นโอกาสสุดท้ายของคุณ",
  str_n32_multiline_11_name_desc_long = "คุณหลบเลี่ยงผู้ไล่ตามตามแผน และมาถึงหน้า Joshua ตามกำหนด เกมหมากรุกใหม่กำลังจะเริ่มขึ้น",
  str_n32_multiline_12_name_desc_long = "คุณพยายามปลอบใจ Dark Angel ด้วยการร้องเพลงที่เธอร้องให้ Mia สิ่งนี้ทำให้นึกถึงอดีตของเธอที่ Dark Angel ซึ่งความพยายามลอบสังหารล้มเหลวและชวาร์ตษ์หนุ่มเอาชนะเธอไปได้... ความทรงจำของเธอยังชัดเจน ทำให้เธอให้อภัยชวาร์ตษ์ได้ยากขึ้น",
  str_n32_multiline_13_name_desc_long = "Schwartz ไม่เห็น Dark Angel แต่เผชิญหน้ากับทหารที่ไล่ตามคุณ คุณแนะนำทุกคนไปยังอัฒจันทร์ก่อนที่มังกรจะโจมตีและจัดการเพื่อต่อสู้กับมัน มีอาคอยปลอบใจดาร์คแองเจิลด้วย ขณะที่คุณร็อตอยู่กับโจชัว และสิ่งต่างๆ ก็เปลี่ยนแปลงไปในทางที่ดีขึ้นอย่างมาก",
  str_n32_multiline_14_name_desc_long = "ความจริงอาจเป็นเรื่องยากที่จะยอมรับ แต่เพื่อก้าวต่อไป เราต้องเรียนรู้ที่จะเผชิญกับมันทั้งหมด Caleb, Schwartz, the Dark Angel, Mia และ Ms. Rot... เมื่อการต่อสู้ครั้งสุดท้ายใกล้เข้ามา ทุกคนมีความจริงของตัวเองที่ฝังแน่นอยู่ในหัวใจของพวกเขา",
  str_n32_multiline_15_name_desc_long = "คุณต่อสู้อย่างเด็ดขาดกับ White Demon และผลักเธอไปสู่ความพ่ายแพ้ ปีศาจขาวตั้งใจจะลากคุณไปที่หลุมฝังศพพร้อมกับเธอ ในขณะที่เทวทูตมืดเลือกที่จะเผชิญหน้ากับปีศาจขาวเพียงลำพังหลังจากคืนดีกับครอบครัวของเธอแล้ว ตัวตนที่แตกแยกทั้งสองกลับมาพบกันอีกครั้งในที่สุด",
  str_n32_multiline_16_name_desc_long = "คุณออกจาก Crystal of Eternal Memory สำเร็จหลังจากช่วย Joshua อย่างไรก็ตาม ดูเหมือนว่าโจชัวจะสูญเสียความทรงจำทั้งหมดของเธอไปและเลือกที่จะออกเดินทางครั้งใหม่เพียงลำพัง เมื่อเป็นเรื่องยากที่จะเผชิญหน้ากับปัจจุบัน ผู้คนมักเลือกที่จะหมกมุ่นอยู่กับอดีตเพื่อหลีกหนี เมื่อผู้คนฟื้นคืนความกล้าหาญในการใช้ชีวิตเท่านั้น เราจึงจะก้าวไปสู่อนาคตใหม่ได้",
  str_n32_multiline_17_name_desc_long = "—",
  str_n32_multiline_18_name_desc_long = "—",
  str_n32_multiline_19_name_desc_long = "—",
  str_n32_multiline_20_name_desc_long = "—",
  str_n32_multiline_21_name_desc_long = "—",
  str_n32_multiline_22_name_desc_long = "—",
  str_n32_multiline_23_name_desc_long = "—",
  str_n32_multiline_24_name_desc_long = "—",
  str_n32_multiline_doc_lock = "ก้าวไปข้างหน้าอย่างกล้าหาญกันเถอะ บางทีเราอาจจะเจอเรื่องไม่คาดฝันระหว่างทางก็ได้",
  str_n32_multiline_doc_role_1 = "มิสบลังค์",
  str_n32_multiline_doc_role_2 = "โจชัว",
  str_n32_multiline_doc_role_3 = "ชาโรนา",
  str_n32_multiline_doc_role_4 = "ออตโต",
  str_n32_multiline_doc_roledesc_1 = "อดีตกัปตันของ Nightwatch ซึ่งอายุยังเป็นปริศนา\nเธอได้รับบาดเจ็บและต้องล่าถอยระหว่างการรบที่ Umbraton ในปี 1988 Morning Calendar หลังจากถูก Darkover ปิดล้อม และต่อมาได้กลายเป็นไกด์นำเที่ยวที่สง่างาม\nจนถึงทุกวันนี้ ตำนานเกี่ยวกับตัวตนในอดีตของเธอ—Ms. Rot ผู้นำแห่งความตายและการทำลายล้าง—ยังคงวนเวียนอยู่ในมุมอันเงียบสงบของ Lumopolis...",
  str_n32_multiline_doc_roledesc_2 = "ลูกสาวของนักวิชาการที่มีชื่อเสียงและ \"ภรรยาผู้ล่วงลับ\" ของ City Lord ในตอนนั้น ภายใต้แรงกดดันมหาศาล เธอตกหลุมรักและแต่งงานกับชวาร์ตษ์ อย่างไรก็ตาม พ่อของเธอไม่ได้เห็นวันแต่งงานของเธอ ในขณะที่เขาเสียชีวิตในกองเพลิง\nใน Morning Calendar ปี 1992 มีการประกาศอย่างเป็นทางการว่า Joshua ถึงแก่กรรมเนื่องจากอาการป่วย",
  str_n32_multiline_doc_roledesc_3 = "เกิดในลูโมโปลิส เธอทราบตั้งแต่อายุยังน้อยว่าพ่อแม่ของเธอเสียชีวิตทั้งคู่และถูกพาตัวไปอยู่ในความดูแลของผู้อาวุโสของตระกูลคาร์ติมา ใน Morning Calendar ปี 1988 ครอบครัว Kartima ตกเป็นที่ต้องการตัวของ Lumopolis เนื่องจากก่อการรัฐประหาร และ Sharona โชคดีที่หนีออกจากเมืองได้ ภายหลังเธอได้เข้าร่วมกองกำลังพันธมิตรเพื่อมีส่วนร่วมในการโจมตีตอบโต้กับ Darkover และในที่สุดก็ได้เป็นผู้บัญชาการกองพันอิลลูมินา",
  str_n32_multiline_doc_roledesc_4 = "เกิดในตระกูลทรอยที่ทรงพลังซึ่งมีอิทธิพลหลักคือสภาผู้เฒ่า หลังจากเจ้าเมืองคนก่อนถูกสังหาร ข่าวลือเริ่มชี้นิ้วไปที่ตระกูลทรอย แต่ข่าวลือเหล่านี้ก็จางหายไปอย่างรวดเร็ว เขาวางแผนที่จะฝึกหลานสาวให้เป็นผู้สืบทอด อย่างไรก็ตาม ภายหลังเธอได้รับการจดทะเบียนอย่างเป็นทางการว่าเสียชีวิต",
  str_n32_multiline_doc_name_1 = "ภูมิหลังของ Ms. Blanc",
  str_n32_multiline_doc_name_2 = "จดหมายถึง Montagues",
  str_n32_multiline_doc_name_3 = "นิทานสาวผมแดง",
  str_n32_multiline_doc_name_4 = "Roshee กลับสู่เส้นทางอันชอบธรรม",
  str_n32_multiline_doc_name_5 = "จดหมายเผาไหม้",
  str_n32_multiline_doc_name_6 = "สาวผมแดงและผู้สูงอายุ",
  str_n32_multiline_doc_name_7 = "บ้านมอนตะคิว",
  str_n32_multiline_doc_name_8 = "หญิงสาวแห่งคำทำนาย",
  str_n32_multiline_doc_tips_1 = "ปลดล็อกประวัติของ Ms. Blanc ในอดีตแล้ว",
  str_n32_multiline_doc_tips_2 = "จดหมายเหตุการณ์ที่ผ่านมาถึง Montagues ปลดล็อค",
  str_n32_multiline_doc_tips_3 = "กิจกรรมที่ผ่านมา เรื่องเล่าของสาวผมแดง ปลดล็อคแล้ว",
  str_n32_multiline_doc_tips_4 = "กิจกรรมที่ผ่านมา Roshee กลับสู่เส้นทางอันชอบธรรมที่ปลดล็อกแล้ว",
  str_n32_multiline_doc_tips_5 = "เหตุการณ์ที่ผ่านมา จดหมายที่ถูกเผาไหม้ถูกปลดล็อค",
  str_n32_multiline_doc_tips_6 = "กิจกรรมที่ผ่านมา เด็กสาวผมแดงและผู้เฒ่าถูกปลดล็อคแล้ว",
  str_n32_multiline_doc_tips_7 = "เหตุการณ์ที่ผ่านมา บ้าน Montague ปลดล็อค",
  str_n32_multiline_doc_tips_8 = "ปลดล็อคกิจกรรมในอดีต Maiden of Prophecy แล้ว",
  str_n32_multiline_doc_desc_1 = "คุณบลองก์เป็นญาติห่างๆ ของเลดี้โจชัว อย่างไรก็ตาม ทั้งสองคนไม่ได้เกี่ยวข้องกันทางสายเลือด คุณบล็องแสดงความสามารถที่น่าอัศจรรย์ตั้งแต่ยังเด็ก แต่ก็ต้องทนทุกข์กับความผิดหวังที่ไม่มีที่ที่จะใช้ความสามารถของเธอให้เป็นประโยชน์ เมื่อต้องเผชิญกับพรมากมายของการมีลูกที่มีพรสวรรค์ พ่อแม่ของเธอจึงไม่มีทางเลือกอื่นนอกจากส่งเธอไปอยู่ในมือของ Caleb แต่หลังจากนั้นเธอก็ได้พบกับ Lady Joshua โดยไม่คาดคิด พวกเขาสองคนตีกัน สร้างสายสัมพันธ์ที่แน่นแฟ้นและมีส่วนร่วมในการสนทนาที่เคลื่อนไหวได้จากการพบกันครั้งแรก ด้วยเหตุนี้ Joshua จึงสอนคุณ Blanc เป็นเวลาหลายปี",
  str_n32_multiline_doc_desc_2 = "ในกองจดหมายที่ถูกเผามีจดหมายซ่อนอยู่ซึ่งเขียนโดยพ่อของคาเลบ ในจดหมาย ดูเหมือนว่าพ่อของ Caleb จะตั้งปณิธานบางอย่างไว้ โดยแสดงความปรารถนาอย่างจริงใจต่อผู้รับ",
  str_n32_multiline_doc_desc_3 = "แม่ที่ตื่นขึ้นของ Dragonkin ได้ให้กำเนิดลูกสาวสองคน มรดกของเธอทำให้เธอสูญเสียการควบคุมและครอบครัวของเธอถูกประหารชีวิต เพื่อปกป้องมังกรของเธอที่กำลังจะฟักตัว ลูกสาวคนโตจึงเลือกที่จะพเนจรไปจนตั้งถิ่นฐานในอัมบราตัน ลูกสาวคนเล็กเติบโตขึ้นโดยไม่รู้ว่าแม่ของเธอถูกฆ่าโดยเผ่าของเธอ",
  str_n32_multiline_doc_desc_4 = "แม้ว่าออตโตจะไม่มีลูกเป็นของตัวเอง แต่เขาก็ปฏิบัติต่อโรชี หลานสาวของเขาเสมอ ซึ่งต่อมากลายเป็นหนึ่งในสี่ทูตสวรรค์ ไมเคิล ราวกับว่าเธอเป็นลูกสาวของเขาเอง เมื่อเธอยังเด็ก โรชีเคยสนุกกับการตระเวนไปตามตรอกซอกซอยและท้องถนน จับหัวขโมยและคนร้ายสารพัด แต่ภายใต้การแนะนำของอ็อตโต เธอค่อยๆ หันเหความสนใจไปสู่สิ่งที่ยิ่งใหญ่กว่า ในปฏิทินเช้าปี 1988 จู่ๆ โรชีก็หนีออกจากบ้านโดยไม่มีการเตือนล่วงหน้าแม้แต่น้อย",
  str_n32_multiline_doc_desc_5 = "เหตุผลที่ Roshee หลานสาวของ Otto หนีออกจากบ้านก็เพราะว่าเธอได้รับบันทึกรายการหลักฐานทั้งหมดที่ระบุว่า Otto ลุงของเธอเป็นคนวาง Eclipsites ใน Lumopolis หนึ่งปีก่อนหน้านั้นและยุยงให้เกิดการจลาจล โรชีรับไม่ได้ที่มันจะเป็นความจริง เพราะเชื่อว่าลุงของเธอจะไม่ทำเรื่องแบบนี้ ดังนั้น Roshee จึงทิ้งจดหมายไว้ให้ Sharona เพื่อนของเธอ และเธอตัดสินใจที่จะอยู่ห่างจากครอบครัวของเธอและเข้าร่วมกองกำลังเดินทาง...",
  str_n32_multiline_doc_desc_6 = "เด็กหญิงผมแดงพาลงมาจากหอคอยสูงซึ่งผู้อาวุโสของตระกูลคาร์ติมาถูกคุมขังในข้อหาต่อต้านมีม สร้างความประหลาดใจให้กับเด็กสาวผมแดง ผู้เฒ่าพูดแบบเดียวกับที่แม่ของเธอพูด \"คุณไม่ใช่คนที่จะช่วยครอบครัวคาร์ติมา\" สาวผมแดงรู้ว่าผู้เฒ่ากำลังรอชาโรน่าน้องสาวของเธอ แต่เธอรู้สึกว่าเรื่องนั้นไม่สำคัญกับเธออีกต่อไป",
  str_n32_multiline_doc_desc_7 = "Pyrrhus, Gautier... มอนทาคิว นี่คือชื่อบ้านที่กบฏต่อตระกูล Schwartz ซึ่งเป็นชื่อที่สูญหายไปตามกาลเวลา ความเกลียดชังทำให้ผู้รอดชีวิตตาบอด ทำให้พวกเขากลายเป็นเบี้ยที่เหมาะสำหรับผู้สมรู้ร่วมคิด",
  str_n32_multiline_doc_desc_8 = "ชาโรน่าวิ่งเข้าไปหาผู้เฒ่าข้างหอคอยที่พังทลาย ผู้เฒ่าบอกเธอว่าตามคำทำนาย Sharona เป็นคนเดียวที่สามารถช่วยตระกูล Kartima ได้ เขาปรารถนาให้ Sharona สืบทอด Azure Flame Katana ที่สืบทอดจากรุ่นสู่รุ่นโดยผู้อาวุโสของตระกูล Kartima และท้ายที่สุดจะแบกรับภาระในการรักษาความรุ่งโรจน์ในอนาคตของสายเลือดของพวกเขา",
  str_n32_multiline_doc_lockdesc_1 = "เมื่อไร <color=#ffe062>แคร็ก</color>ฟังสิ่งที่ยามพูดที่ทางเข้าของ <color=#ffe062>ห้องโถงของ Schwartz Mansion</color>.",
  str_n32_multiline_doc_lockdesc_2 = "เมื่อไร <color=#ffe062>แคร็ก</color>ให้ความสนใจกับสิ่งที่อยู่ใต้เท้าของคุณระหว่างทางไป <color=#ffe062>จัตุรัสกลาง</color>...",
  str_n32_multiline_doc_lockdesc_3 = "เมื่อไร <color=#ffe062>แคร็ก</color>ดูเหมือนว่าจะมีคนขวางทางคุณเมื่อคุณกำลังจะออกจาก <color=#ffe062>จัตุรัสกลาง</color>...",
  str_n32_multiline_doc_lockdesc_4 = "เมื่อสิ่งต่าง ๆ เริ่มต้นขึ้น <color=#ffe062>ระเบิด</color>ดูเหมือนว่าคุณจะได้ยินเสียงบางอย่างเมื่อซ่อนตัวอยู่รอบๆ <color=#ffe062>จัตุรัสกลาง</color>...",
  str_n32_multiline_doc_lockdesc_5 = "เมื่อสิ่งต่าง ๆ เริ่มต้นขึ้น <color=#ffe062>ระเบิด</color>ระวังร่างที่คุ้นเคยเมื่อเดินไปตามเส้นทางรอบๆ <color=#ffe062>จัตุรัสกลาง</color>.",
  str_n32_multiline_doc_lockdesc_6 = "เมื่อสิ่งต่าง ๆ เริ่มต้นขึ้น <color=#ffe062>ระเบิด</color>ให้ความสนใจกับรูปทรงของอาคารเมื่อออกจาก <color=#ffe062>จัตุรัสกลาง</color>.",
  str_n32_multiline_doc_lockdesc_7 = "เมื่อสิ่งต่าง ๆ เริ่มต้นขึ้น <color=#ffe062>ยุบ</color>ชี้ทางหนีให้ขุนนางสองคนที่ <color=#ffe062>จัตุรัสกลาง</color>.",
  str_n32_multiline_doc_lockdesc_8 = "เมื่อสิ่งต่าง ๆ เริ่มต้นขึ้น <color=#ffe062>ยุบ</color>ให้ความสนใจกับหอคอยที่พังทลายเมื่อออกจาก <color=#ffe062>จัตุรัสกลาง</color>.",
  str_n32_multiline_doc_unlock_1 = "Ms. Blanc และ Lady Joshua มีประวัติร่วมกันหรือไม่!",
  str_n32_multiline_doc_unlock_2 = "พ่อของ Caleb เขียนจดหมายแบบนี้ได้อย่างไร!",
  str_n32_multiline_doc_unlock_3 = "เรื่องราวของสาวผมแดงเป็นแค่นิทานจริงหรือ?",
  str_n32_multiline_doc_unlock_4 = "ดูเหมือนว่า Otto ก็มีจุดอ่อนที่คาดไม่ถึงเช่นกัน...",
  str_n32_multiline_doc_unlock_5 = "หลานสาวหนีออกจากบ้านเพราะสิ่งที่ Otto ทำหรือเปล่า?",
  str_n32_multiline_doc_unlock_6 = "เด็กสาวผมแดงคือ Leona น้องสาวแท้ๆ ของ Sharona จริงหรือ?!",
  str_n32_multiline_doc_unlock_7 = "ชื่อเหล่านั้นหายไปตามกาลเวลา... ดูเหมือนไม่คุ้นเคยเหรอ?",
  str_n32_multiline_doc_unlock_8 = "ในที่สุดชาโรน่าก็ได้พบกับคนที่รอเธออยู่...",
  str_n32_multiline_lock_tips1 = "ฉันยังไม่มีเงื่อนงำใดๆ",
  str_n32_multiline_lock_tips2 = "ไปและค้นหาตำแหน่งที่ระบุ",
  str_n32_multiline_desc_1 = "อดีตถูกรีเซ็ต คริสตัลกำลังรอการตัดสินใจของคุณ",
